<?php
declare(strict_types=1);
require __DIR__.'/../../functions.php';
require __DIR__.'/../../includes/release_updater.php';
require __DIR__.'/../../includes/github_release_updater.php';
$n=0; $assert=static function(bool $ok,string $msg)use(&$n):void{$n++;if(!$ok)throw new RuntimeException($msg);};
$base=rtrim(sys_get_temp_dir(),DIRECTORY_SEPARATOR).'/github-source-test-'.bin2hex(random_bytes(8));
$app=$base.'/app'; $zipPath=$base.'/archive.zip'; @mkdir($base,0700,true); @mkdir($app,0700,true); foreach(['assets','includes','tabs','storage','pdf','svg','uploads'] as $d) mkdir($app.'/'.$d,0700,true);
$put=static function(string $p,string $data):void { if(file_put_contents($p,$data)===false) throw new RuntimeException('write failed'); };
foreach(['index.php'=>'old-index','functions.php'=>'same-functions','.htaccess'=>'guard','includes/release_config.php'=>'private-config','storage/secret.json'=>'private-data','pdf/sensitive.pdf'=>'pdf','svg/logo.svg'=>'logo','uploads/image.png'=>'image','assets/portal.css'=>'old-css'] as $p=>$v) $put($app.'/'.$p,$v);
$make=static function(string $path,array $files,?string $link=null):void { $z=new ZipArchive(); if($z->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true) throw new RuntimeException('zip'); foreach($files as $p=>$v) $z->addFromString($p,$v); if($link!==null) $z->setExternalAttributesName($link,ZipArchive::OPSYS_UNIX,0120777 << 16); $z->close(); };
$files=['document-v1/index.php'=>'new-index','document-v1/functions.php'=>'same-functions','document-v1/assets/portal.css'=>'new-css','document-v1/storage/secret.json'=>'replace','document-v1/includes/release_config.php'=>'replace','document-v1/customers.json'=>'replace','document-v1/pdf/sensitive.pdf'=>'replace','document-v1/svg/logo.svg'=>'replace','document-v1/uploads/image.png'=>'replace','document-v1/.htaccess'=>'replace','document-v1/includes/private.json'=>'replace'];
$make($zipPath,$files);
$assert(!portal_github_release_allowed_file('storage/secret.json') && !portal_github_release_allowed_file('customers.json') && !portal_github_release_allowed_file('includes/private.json') && !portal_github_release_allowed_file('includes/release_config.php'), 'Data and local settings are excluded');
$assert(portal_github_release_allowed_file('includes/fpdf/font/helvetica.json') && !portal_github_release_allowed_file('includes/fpdf/font/secret.json'), 'Only specific code font metrics may use JSON');
$plan=portal_github_release_compare($app,$zipPath,'v1');
$assert(($plan['ok'] ?? false) && $plan['changed']===['assets/portal.css','index.php'] && $plan['unchanged']===['functions.php'], 'Review shows only changed program files');
$bad=portal_release_install_package($app,$zipPath,'','v1','v1',str_repeat('0',64),'github',$plan['before']);
$assert(!($bad['ok'] ?? false) && file_get_contents($app.'/index.php')==='old-index','Unreviewed archive digest cannot install');
$put($app.'/functions.php','local-change');
$bad=portal_release_install_package($app,$zipPath,'','v1','v1',$plan['manifest_sha256'],'github',$plan['before']);
$assert(!($bad['ok'] ?? false) && file_get_contents($app.'/index.php')==='old-index','Local changes since review stop installation');
$put($app.'/functions.php','same-functions');
$installed=portal_release_install_package($app,$zipPath,'','v1','v1',$plan['manifest_sha256'],'github',$plan['before']);
$assert(($installed['ok'] ?? false) && $installed['code']==='installed' && file_get_contents($app.'/index.php')==='new-index' && file_get_contents($app.'/assets/portal.css')==='new-css','Approved code is installed');
foreach(['storage/secret.json'=>'private-data','includes/release_config.php'=>'private-config','.htaccess'=>'guard','pdf/sensitive.pdf'=>'pdf','svg/logo.svg'=>'logo','uploads/image.png'=>'image'] as $p=>$v) $assert(file_get_contents($app.'/'.$p)===$v,"Protected path remains unchanged: $p");
$plan2=portal_github_release_compare($app,$zipPath,'v1');
$assert(($plan2['ok'] ?? false) && $plan2['changed']===[], 'Identical code is skipped');
$files['document-v1/index.php']='tampered'; $make($zipPath,$files);
$bad=portal_release_install_package($app,$zipPath,'','v1','v1',$plan2['manifest_sha256'],'github',$plan2['before']);
$assert(!($bad['ok'] ?? false) && file_get_contents($app.'/index.php')==='new-index','Changed archive after review is rejected');
$files['document-v1/../evil.php']='oops'; $make($zipPath,$files); $assert(!(portal_github_release_compare($app,$zipPath,'v1')['ok'] ?? false),'Traversal rejected even in skipped entries'); unset($files['document-v1/../evil.php']);
$files['other-v1/another.txt']='x'; $make($zipPath,$files); $assert(!(portal_github_release_compare($app,$zipPath,'v1')['ok'] ?? false),'Multiple roots rejected'); unset($files['other-v1/another.txt']);
$files['document-v1/assets/link.js']='target'; $make($zipPath,$files,'document-v1/assets/link.js'); $assert(!(portal_github_release_compare($app,$zipPath,'v1')['ok'] ?? false),'ZIP symlink rejected');
$temp=portal_release_create_temp_file((string)realpath($app));
$assert(is_string($temp) && !str_starts_with((string)realpath($temp),(string)realpath($app).DIRECTORY_SEPARATOR), 'Download temp file is outside application');
if (is_string($temp)) unlink($temp);
$files['document-v1/newroot.php']='ignored'; $files['document-v1/includes/newdir/new.php']='code'; $make($zipPath,$files);
$assert((portal_github_release_compare($app,$zipPath,'v1')['code'] ?? '')==='target_parent_missing','A missing destination directory blocks the plan');
unset($files['document-v1/includes/newdir/new.php']); $make($zipPath,$files);
if (function_exists('symlink') && @symlink($base,$app.'/includes/link')) {
    $files['document-v1/includes/link/new.php']='code'; $make($zipPath,$files);
    $assert((portal_github_release_compare($app,$zipPath,'v1')['code'] ?? '')==='target_symlink','Symlinked target directories are blocked');
    unlink($app.'/includes/link');
}
$cacheRoot=__DIR__.'/.github-cache-sandbox'; @mkdir($cacheRoot); @mkdir($cacheRoot.'/storage'); $put($cacheRoot.'/storage/.htaccess',"Require all denied\n");
$count=0; $fetch=static function()use(&$count):array{$count++;return ['ok'=>false,'code'=>'no_published_release'];};
$a=portal_github_release_auto_status($cacheRoot,$fetch,100000); $b=portal_github_release_auto_status($cacheRoot,$fetch,121599); $c=portal_github_release_auto_status($cacheRoot,$fetch,121600);
$assert($count===2 && $a['code']==='no_published_release' && $b['checked_at']===100000 && $c['checked_at']===121600,'Failed checks cached for six hours');
$sha1=str_repeat('a',40); $sha2=str_repeat('b',40);
$marker=['tag'=>'0.0.1','commit'=>$sha1];
$assert(portal_github_release_install_marker($cacheRoot)===null && portal_github_release_install_marker($cacheRoot,'0.0.1',$sha1)===$marker && portal_github_release_install_marker($cacheRoot)===$marker, 'Installed release commit persists safely');
$assert(portal_github_release_install_marker($cacheRoot,'../bad',$sha1)===null && portal_github_release_install_marker($cacheRoot,'0.0.1','bad')===null, 'Invalid marker tag or commit rejected');
$assert(portal_github_release_marker_differs(['ok'=>true,'tag'=>'0.0.1','commit'=>$sha2],$marker), 'Moved tag is detected even when version is unchanged');
$assert(!portal_github_release_marker_differs(['ok'=>true,'tag'=>'0.0.1','commit'=>$sha1],$marker), 'Unchanged commit does not trigger update notice');
$success=static fn(): array => ['ok'=>true,'code'=>'latest_release_found','tag'=>'0.0.1','commit'=>$sha2];
$status=portal_github_release_auto_status($cacheRoot,$success,143200);
$assert(($status['commit'] ?? '')===$sha2 && portal_github_release_marker_differs($status,$marker), 'Auto cache stores and compares the resolved commit');
$guard=$cacheRoot.'/storage/.htaccess'; unlink($guard);
$assert(portal_github_release_auto_status($cacheRoot,$fetch,165000)['code']==='cache_unavailable' && $count===2,'Unprotected cache fails closed without contacting GitHub');
foreach(glob($cacheRoot.'/storage/*') ?: [] as $p) unlink($p); rmdir($cacheRoot.'/storage');rmdir($cacheRoot);
portal_release_remove_tree($base);
echo "PASS: {$n} unsigned GitHub source-release checks.\n";
